//3.
var FoodBaseProblemMatcherUtil = Class.create();

FoodBaseProblemMatcherUtil.prototype = {

    initialize: function() {},

    // Main function
    matchOrCreate: function(complaintSysId) {

        // Get Food Complaint
        var complaint = new GlideRecord(
            'x_snc_campus_foo_1_food_complaint'
        );

        if (!complaint.get(complaintSysId)) {
            gs.error(
                'FoodBaseProblemMatcherUtil: Complaint not found ' +
                complaintSysId
            );
            return;
        }

        // Find Base Problem using ONLY Use Case + Mess Hall
        var baseProblem = this._findExisting(complaint);

        if (baseProblem) {

            // Existing Base Problem found
            this._updateExisting(complaint, baseProblem);

        } else {

            // No Base Problem found
            this._createNew(complaint);
        }
    },


    // Find Base Problem using ONLY:
    // Use Case + Mess Hall
    _findExisting: function(complaint) {

        var bp = new GlideRecord(
            'x_snc_campus_foo_1_food_base_problem'
        );

        bp.addQuery('use_case', complaint.use_case);
        bp.addQuery('mess_hall', complaint.mess_hall);

        bp.query();

        if (bp.next()) {
            return bp;
        }

        return null;
    },


    // Existing Base Problem found
    _updateExisting: function(complaint, bp) {

        // Assign Base Problem to Food Complaint
        complaint.base_problem = bp.getUniqueValue();
        complaint.update();

        // Increase student count
        bp.student_count =
            parseInt(bp.student_count || 0, 10) + 1;

        bp.update();

        gs.info(
            'Food Complaint ' + complaint.number +
            ' linked to existing Base Problem ' + bp.number
        );
    },


    // No Base Problem found
    _createNew: function(complaint) {

        var bp = new GlideRecord(
            'x_snc_campus_foo_1_food_base_problem'
        );

        bp.initialize();

        // Matching fields
        bp.use_case = complaint.use_case;
        bp.mess_hall = complaint.mess_hall;

        // Optional information copied from complaint
        bp.meal_type = complaint.meal_type;
        bp.problem_type = complaint.problem_type;
        bp.problem_type_normalized =
            complaint.problem_type_normalized;

        // First complaint/student
        bp.student_count = 1;

        // Create Base Problem
        var bpSysId = bp.insert();

        // Assign new Base Problem to Food Complaint
        complaint.base_problem = bpSysId;
        complaint.update();

        gs.info(
            'Food Complaint ' + complaint.number +
            ' created new Base Problem ' + bp.number
        );
    },


    type: 'FoodBaseProblemMatcherUtil'
};

